  'v = v₀e^(−t/τ)，滑行距离 x = mv₀R/(B²L²)': ['v = v₀e^(−t/τ), coasting distance x = mv₀R/(B²L²)', 'v = v₀e^(−t/τ), Gleitstrecke x = mv₀R/(B²L²)'],
  '收尾速度 v = mgR/(B²L²)': ['Terminal velocity v = mgR/(B²L²)', 'Endgeschwindigkeit v = mgR/(B²L²)'],
