  '厚度（nm）': ['Thickness (nm)', 'Dicke (nm)'],
  '反射率 R': ['Reflectance R', 'Reflexionsgrad R'],
  '单缝衍射': ['Single slit', 'Einzelspalt'],
  '双缝干涉': ['Double slit', 'Doppelspalt'],
  '光栅': ['Grating', 'Gitter'],
